 async function identity(){const r=await client()?.auth.getUser();if(r?.error||!r?.data?.user)throw Error('Connectez-vous à votre compte professionnel.');const p=await client().from('profiles').select('id,company_id,role').eq('id',r.data.user.id).single();if(p.error||!p.data)throw Error('Profil professionnel inaccessible.');return p.data;}
