  body.append(n('p','Demande initiale : '+value(s.original_pallets)+' palettes · '+value(s.original_weight)+' kg. Quantités ci-dessus déclarées pour cette version.','lv-reference'),n('p','Document '+row.id+' · Enregistré le '+date(row.created_at)+(v.external_ecmr_reference?' · Référence e-CMR externe : '+v.external_ecmr_reference:''),'lv-reference'));
