  add('h1',documentLabel);add('p',s.is_test?'EXERCICE FICTIF — AUCUN TRANSPORT RÉEL':row.kind==='waybill'?'À COMPLÉTER ET À FAIRE SIGNER AU CHARGEMENT ET À LA LIVRAISON':row.state==='draft'?'BROUILLON — NON ÉMIS':'VERSION ÉMISE PAR LE DONNEUR D’ORDRE — SIGNATURE DES PARTIES À RECUEILLIR','badge');
